            Box(Modifier.testTag("radio-rtl")) {
                RadioGroup(
                    value = selected,
                    onValueChange = { selected = it },
                    modifier = Modifier.width(IntrinsicSize.Max).testTag("radio-rtl-group"),
                ) {
                    options.forEach { option ->
                        DescribedRow(option)
                    }
                }
            }
        }
    }
